function initSwAccordion(data,items){
  if(!items||!items.length)return;
  var mq=window.matchMedia("(max-width:1000px)");
  function shut(btn,animate){
    var acc=btn.nextElementSibling;
    btn.classList.remove("open");btn.setAttribute("aria-expanded","false");
    if(acc&&acc.classList.contains("sw-acc"))gsap.to(acc,{height:0,duration:animate&&!reduced?.4:0,ease:"power3.inOut",overwrite:!0});
  }
  items.forEach(function(btn,i){
    var d=data[+btn.dataset.sw]||data[i];if(!d)return;
    var idx=document.createElement("span");
    idx.className="sw-idx";idx.setAttribute("aria-hidden","true");
    idx.textContent=String(i+1).padStart(2,"0");
    btn.insertBefore(idx,btn.firstChild);
    var tog=document.createElement("span");
    tog.className="sw-toggle";tog.setAttribute("aria-hidden","true");
    tog.innerHTML="<i></i><i></i>";
    btn.appendChild(tog);
    var acc=document.createElement("div");
    acc.className="sw-acc";acc.id="sw-acc-"+i;
    var inner=document.createElement("div");inner.className="sw-acc-in";
    var desc=document.createElement("p");desc.className="sw-acc-desc";desc.textContent=d.desc;
    var tag=document.createElement("p");tag.className="sw-acc-tag";tag.textContent=d.tagline;
    var link=document.createElement("a");link.className="btn sw-acc-btn";link.href="services.html";
    link.innerHTML="<span>View service</span><span>\u2197</span>";
    inner.appendChild(desc);inner.appendChild(tag);inner.appendChild(link);
    acc.appendChild(inner);
    btn.insertAdjacentElement("afterend",acc);
    btn.setAttribute("aria-controls",acc.id);
    btn.setAttribute("aria-expanded","false");
    btn.addEventListener("click",function(){
      if(!mq.matches)return;
      var wasOpen=btn.classList.contains("open");
      items.forEach(function(o){if(o.classList.contains("open"))shut(o,!0)});
      if(!wasOpen){
        btn.classList.add("open");btn.setAttribute("aria-expanded","true");
        gsap.to(acc,{height:"auto",duration:reduced?0:.45,ease:"power3.out",overwrite:!0,onComplete:function(){ScrollTrigger.refresh()}});
      }else ScrollTrigger.refresh();
    });
  });
  mq.addEventListener("change",function(e){
    if(!e.matches)items.forEach(function(o){
      o.classList.remove("open");o.setAttribute("aria-expanded","false");
      var a=o.nextElementSibling;if(a&&a.classList.contains("sw-acc"))gsap.set(a,{clearProps:"height"});
    });
  });
}

/* ---------- SECTION REVEALS — staggered entrance + clip-path media wipe ----------
   Cards enter a batch at a time (roughly a row per batch) with a short stagger, and
   any media inside wipes open via clip-path. GSAP's inline props are cleared on
   completion so CSS :hover transforms keep working (an inline transform would
   otherwise beat the stylesheet). Bails out entirely when GSAP is unavailable or the
   visitor asked for reduced motion, in which case everything renders as normal. */
(function(){
  if(typeof gsap==="undefined"||typeof ScrollTrigger==="undefined")return;
  if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
  var canClip=!!(window.CSS&&CSS.supports&&CSS.supports("clip-path","inset(0 0 50% 0)"));

  function reveal(selector,opts){
    opts=opts||{};
    var items=gsap.utils.toArray(selector);
    if(!items.length)return;
    var stagger=opts.stagger||.06,
        pick=function(list){
          return opts.media?list.map(function(el){return el.querySelector(opts.media)}).filter(Boolean):[];
        };
    gsap.set(items,{opacity:0,y:opts.y||30});
    if(canClip)gsap.set(pick(items),{clipPath:"inset(0 0 100% 0)"});
    ScrollTrigger.batch(items,{
      start:opts.start||"top 90%",
      onEnter:function(batch){
        gsap.to(batch,{opacity:1,y:0,duration:.6,ease:"power3.out",stagger:stagger,overwrite:true,
          onComplete:function(){gsap.set(batch,{clearProps:"transform,opacity"})}});
        if(!canClip)return;
        var media=pick(batch);
        if(!media.length)return;
        gsap.to(media,{clipPath:"inset(0 0 0% 0)",duration:.75,ease:"power3.out",stagger:stagger,delay:.06,overwrite:true,
          onComplete:function(){gsap.set(media,{clearProps:"clipPath"})}});
      }
    });
  }

  reveal(".clients-grid .client-card",{media:"img"});
  reveal(".camp-track .camp-card",{media:".img",stagger:.07});
  reveal(".testi-track .testi-card",{stagger:.07});
  reveal("#peopleBrief .team-card",{media:".team-avatar",stagger:.1});
})();
